  const [error,setError]=useState(''),[fitStatus,setFitStatus]=useState(''),[tab,setTab]=useState(()=>state.risk?'pluvial':'explore'),[expanded,setExpanded]=useState(()=>window.innerWidth>850);
  const [pluvialMeta,setPluvialMeta]=useState<any>(null),[pluvialError,setPluvialError]=useState(''),[exposure,setExposure]=useState<any>(null),[exposureError,setExposureError]=useState('');
  const [refinementMeta,setRefinementMeta]=useState<any>(null),[refinementError,setRefinementError]=useState('');
  const [assessmentMeta,setAssessmentMeta]=useState<any>(null),[assessmentError,setAssessmentError]=useState('');
  const [buildingsMeta,setBuildingsMeta]=useState<BuildingsMeta|null>(null),[buildingsError,setBuildingsError]=useState(''),[focusTarget,setFocusTarget]=useState<MapFocus|null>(null);
  const [cadastreMeta,setCadastreMeta]=useState<BuildingsMeta|null>(null),[cadastreError,setCadastreError]=useState('');
  const [historyMeta,setHistoryMeta]=useState<any>(null),[historyError,setHistoryError]=useState('');
