  const [rainfallMeta,setRainfallMeta]=useState<RainfallMeta|null>(null),[rainfallError,setRainfallError]=useState(''),[rainStats,setRainStats]=useState<any>(null),[rainStatsError,setRainStatsError]=useState('');
  const [customDraft,setCustomDraft]=useState(state.customBasemap);
  const [navigationKey,setNavigationKey]=useState(0);
  const [mapStatus,setMapStatus]=useState('Connecting real datasets…'),[mapError,setMapError]=useState(false),[selection,setSelection]=useState<any>(null),[toast,setToast]=useState('');
  const [viewBounds,setViewBounds]=useState<number[]|null>(null),[fitting,setFitting]=useState(false);
  const [pipeDrawing,setPipeDrawing]=useState(false),[pipeArea,setPipeArea]=useState<any>(null),[pipeCandidates,setPipeCandidates]=useState<any>(null),[pipeIds,setPipeIds]=useState<string[]>([]);
  const [cloggingInputs,setCloggingInputs]=useState<CloggingInputs>(defaultCloggingInputs),[cloggingScenario,setCloggingScenario]=useState<any>(null),[cloggingBusy,setCloggingBusy]=useState(false),[cloggingError,setCloggingError]=useState(''),[cloggingDirty,setCloggingDirty]=useState(false);
  const [cloggingMode,setCloggingMode]=useState<CloggingMode>('depth_clogged'),[cloggingVisible,setCloggingVisible]=useState(true);
  const [cloggingRiverFilter,setCloggingRiverFilter]=useState<RiverFilter>('all');
  const cloggingRequest=useRef(new LatestRequest());
