  const outside=scale?.id!=='whole'&&scale&&viewBounds&&(viewBounds[0]<scale.bbox[0]||viewBounds[1]<scale.bbox[1]||viewBounds[2]>scale.bbox[2]||viewBounds[3]>scale.bbox[3]);
